import {IMAGE_CONCURRENCY} from './cell-requests.js';
// Immutable aligned science arrays. IndexedDB keeps preloaded exposures across reloads.
export function createFrameCache({memoryBytes=32*1024*1024,diskBytes=128*1024*1024,indexedDB=globalThis.indexedDB}={}){
 const memory=new Map();let bytes=0,opening,serial=Promise.resolve();
 const size=value=>Object.values(value).reduce((n,f)=>n+Object.values(f).reduce((s,v)=>s+(ArrayBuffer.isView(v)?v.byteLength:0),0),0);
 function remember(key,value){if(memory.has(key))bytes-=memory.get(key).bytes;const entry={value,bytes:size(value)};memory.delete(key);memory.set(key,entry);bytes+=entry.bytes;while(bytes>memoryBytes&&memory.size>1){const oldest=memory.keys().next().value;bytes-=memory.get(oldest).bytes;memory.delete(oldest);}return value;}
 const request=r=>new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});
 async function db(){if(!indexedDB)return null;return opening??=new Promise(resolve=>{const r=indexedDB.open('sate-aligned-frames-v1',2);r.onupgradeneeded=()=>{if(r.result.objectStoreNames.contains('frames'))r.result.deleteObjectStore('frames');r.result.createObjectStore('frames',{keyPath:'key'});r.result.createObjectStore('usage',{keyPath:'key'});};r.onsuccess=()=>resolve(r.result);r.onerror=r.onblocked=()=>resolve(null);});}
 async function write(entry){try{const d=await db();if(!d)return;const tx=d.transaction(['frames','usage'],'readwrite'),s=tx.objectStore('frames'),usage=tx.objectStore('usage');const done=new Promise(resolve=>{tx.oncomplete=tx.onerror=tx.onabort=resolve;});s.put(entry);usage.put({key:entry.key,bytes:entry.bytes,used:entry.used});const records=await request(usage.getAll());let total=records.reduce((n,r)=>n+r.bytes,0);records.sort((a,b)=>a.used-b.used);while(total>diskBytes&&records.length){const old=records.shift();s.delete(old.key);usage.delete(old.key);total-=old.bytes;}await done;}catch{/* Private mode / quota: memory cache still works. */}}
 return {peek:key=>{const hit=memory.get(key);return hit?remember(key,hit.value):null;},async get(key){const hit=this.peek(key);if(hit)return hit;try{const d=await db();if(!d)return null;const entry=await request(d.transaction('frames').objectStore('frames').get(key));if(!entry)return null;remember(key,entry.value);serial=serial.then(()=>write({...entry,used:Date.now()}));return entry.value;}catch{return null;}},set(key,value){remember(key,value);serial=serial.then(()=>write({key,value,bytes:size(value),used:Date.now()}));return serial;},flush:()=>serial,clearMemory(){memory.clear();bytes=0;}};
}

// Shared promises: selecting an exposure joins its preload instead of restarting it.
export function createFrameLoader({load,concurrency=IMAGE_CONCURRENCY,onChange=()=>{}}){
 const jobs=new Map(),queue=[];let active=0,closed=false;
 function pump(){while(!closed&&active<concurrency&&queue.length){const job=queue.shift();active++;job.state='loading';Promise.resolve().then(()=>load(job.item)).then(value=>{job.state='ready';job.resolve(value);},error=>{job.state=error.name==='InsufficientCoverageError'?'skipped':'error';job.reject(error);}).finally(()=>{job.promise=null;active--;onChange();pump();});}onChange();}
 return {get(item,priority=false){let job=jobs.get(item.path);if(job?.promise&&job.state!=='error'){if(priority&&job.state==='queued'){queue.splice(queue.indexOf(job),1);queue.unshift(job);}return job.promise;}job={item,state:'queued'};job.promise=new Promise((resolve,reject)=>Object.assign(job,{resolve,reject}));jobs.set(item.path,job);priority?queue.unshift(job):queue.push(job);pump();return job.promise;},state:path=>jobs.get(path)?.state,close(){closed=true;for(const job of queue.splice(0)){job.state='error';job.reject(new DOMException('Cancelled','AbortError'));}},counts(){const values=[...jobs.values()];return {ready:values.filter(j=>j.state==='ready').length,failed:values.filter(j=>j.state==='error').length,total:values.filter(j=>j.state!=='skipped').length,skipped:values.filter(j=>j.state==='skipped').length};}};
}
